<?php

/**
 * A second place for backup copies (not the same computer or disk).
 *
 * Drivers:
 *   none    - no remote copy configured
 *   folder  - another folder: USB drive, network share, NAS, a cloud-synced folder
 *   sftp    - another server over SSH (uses the OpenSSH "ssh" and "scp" programs)
 *
 * Only file names generated by this system are ever sent to a remote, and every
 * name is validated first.
 */
interface RemoteStorage
{
    public function name(): string;

    /** Safe description for the dashboard (never contains secrets). */
    public function describe(): string;

    /** Copy a local file to the remote ($kind is "daily" or "weekly"). Throws on failure. */
    public function upload(string $localPath, string $remoteName, string $kind): void;

    /** Size and SHA-256 of the file as it exists on the remote, or null if missing. */
    public function stat(string $remoteName, string $kind): ?array;

    /** @return array<int,array{name:string,size:int,mtime:int}> */
    public function listFiles(string $kind): array;

    public function download(string $remoteName, string $kind, string $localPath): void;

    public function delete(string $remoteName, string $kind): void;

    /** Checks connectivity and write access. @return array{ok:bool,message:string} */
    public function test(): array;
}

final class RemoteFactory
{
    public static function driver(): string
    {
        $driver = strtolower(BackupConfig::env('REMOTE_DRIVER', 'none'));
        return in_array($driver, ['none', 'folder', 'sftp'], true) ? $driver : 'none';
    }

    public static function isConfigured(): bool
    {
        return self::driver() !== 'none';
    }

    /** @throws RuntimeException when the settings are incomplete or unsafe */
    public static function create(): ?RemoteStorage
    {
        switch (self::driver()) {
            case 'folder':
                $path = BackupConfig::env('REMOTE_FOLDER_PATH');
                if ($path === '') {
                    throw new RuntimeException('REMOTE_FOLDER_PATH is not set in .env.');
                }
                return new FolderRemote($path);

            case 'sftp':
                return SftpRemote::fromEnv();

            default:
                return null;
        }
    }

    /** Backup file names are generated by us; anything else is rejected. */
    public static function safeName(string $name): bool
    {
        // "<name>.dump" or its checksum file "<name>.dump.sha256"
        return preg_match('/\Afindit_[A-Za-z0-9_.-]{1,100}\.dump(\.sha256)?\z/', $name) === 1
            && strpos($name, '..') === false;
    }

    public static function safeKind(string $kind): bool
    {
        return $kind === 'daily' || $kind === 'weekly';
    }

    public static function assertValid(string $name, string $kind): void
    {
        if (!self::safeName($name) || !self::safeKind($kind)) {
            throw new InvalidArgumentException('Invalid backup file name.');
        }
    }
}
